"""Fifty distinct GCP use cases and their evidence/remediation contracts.

Each entry produces an independent five-agent ADK SequentialAgent.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class UseCase:
    slug: str
    title: str
    services: tuple[str, ...]
    evidence: str
    remedy: str
    verify: str
    example: str


